  /**
   * allTasks iterates over GET /v1/domain/{serviceName}/task (List all domain tasks).
   *
   * It lists the IDs with {@link DomainApi.listTasks}, then gets each object with
   * {@link DomainApi.getTask}, only when the loop reaches it. An object deleted in the
   * meantime is skipped. Any other error is thrown and stops the loop.
   *
   * The two calls require the IAM action domain:apiovh:task/get.
   *
   * @param serviceName - Service name
   * @param params - the optional parameters
   * @param options - the options of this call: signal, timeout, headers
   * @returns each {@link models.DomainTask}, one at a time: loop with `for await`
   * @throws ForbiddenError when the policy lacks an IAM action this call requires
   * @example
   * for await (const item of client.domain.allTasks(serviceName)) console.log(item);
   */
  allTasks(
    serviceName: string,
    params?: {
      /** Filter the value of function property (like) */
      function?: string | undefined;
      /** Filter the value of status property (=) */
      status?: models.DomainOperationStatusEnum | undefined;
      /** Filter the value of type property (=) */
      type?: models.DomainOperationTypeEnum | undefined;
    },
    options?: RequestOptions,
  ): AsyncIterable<models.DomainTask> {
    return this._each(
      () => this.listTasks(serviceName, params, options),
      (listedId) => this.getTask(serviceName, listedId, options),
    );
  }

